import { Spinner, Button, Card } from "march/ui"

// sihirli küre: soru sorunca küre bir an "düşünür" (dönen halka), sonra bir cevap verir
const ANSWERS = ["Kesinlikle evet ✨", "Pek sanmam 🤔", "Yıldızlar öyle diyor 🌟", "Sonra tekrar sor 🔮"]

export function MagicEightBall() {
  let $thinking = false
  let $answer = "Bir soru düşünün ve sorun."
  const ask = () => {
    $thinking = true
    setTimeout(() => { $answer = ANSWERS[Math.floor(Math.random() * ANSWERS.length)]!; $thinking = false }, 1200)
  }
  return <Card m:theme="night">
    <div sx={{ flex: ["col", "center"], gap: 3, p: 3 }}>
      {() => $thinking ? <Spinner size="lg" colors="brand" label="Küre düşünüyor" /> : <span sx={{ text: "lg" }}>{$answer}</span>}
      <Button variant="primary" disabled={() => $thinking} on:click={ask}>Küreye sor</Button>
    </div>
  </Card>
}

import { Spinner, Button, Card } from "march/ui"
import { save } from "march/icons"

// kaydet düğmesi: kaydederken düğmenin içinde metin boyunda (em), süs olarak dönen halka; metin durumu kendisi söyler
export function SaveButton() {
  let $saving = false
  let $saved = 0
  const run = () => { $saving = true; setTimeout(() => { $saving = false; $saved++ }, 1000) }
  return <Card title="Profil">
    <div sx={{ flex: ["row", "center"], gap: 2 }}>
      <Button variant="primary" icon={save} disabled={() => $saving} on:click={run}>
        {() => $saving ? <span sx={{ flex: ["row", "center"], gap: 1 }}><Spinner size="em" decorative /> Kaydediliyor…</span> : "Kaydet"}
      </Button>
      <span sx={{ color: "muted" }}>{() => ($saved ? `${$saved} kez kaydedildi` : "")}</span>
    </div>
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { SpinnerLab } from "./SpinnerLab.tsx"

// SpinnerLab'in testleri: kaydedince Testler sekmesinde çalışır
test("halka role=status ve adıyla okunur", () => {
  const s = renderTest(() => <SpinnerLab />)
  const sp = s.find("Boyut lg")
  expect(sp?.getAttribute("role")).toBe("status")
})

test("decorative halka yardımcı teknolojiden gizli, rolü yok", () => {
  const s = renderTest(() => <SpinnerLab />)
  const em = s.get(".lab-em")
  expect(em?.getAttribute("aria-hidden")).toBe("true")
  expect(em?.hasAttribute("role")).toBe(false)
})

test("renk listesi custom, color tek renk", () => {
  const s = renderTest(() => <SpinnerLab />)
  expect(s.get(".lab-pair")?.getAttribute("data-m-colors")).toBe("custom")
  expect(s.get(".lab-orange")?.getAttribute("data-m-color")).toBe("brand-orange")
})

test("label erişimcisi canlı", async () => {
  const s = renderTest(() => <SpinnerLab />)
  expect(s.get(".lab-count")?.getAttribute("aria-label")).toBe("3 dosya kaldı")
  await s.click("Bir dosya bitti")
  expect(s.get(".lab-count")?.getAttribute("aria-label")).toBe("2 dosya kaldı")
})
